        "title": "Falsification Test: Can the roundtrip invariant coset_evals_to_cell(cell_to_coset_evals(cell)) == cell be violated for valid field elements?",
        "severity": "Medium",
        "mindset": "Formal Verification Engineer",
        "is_boundary_check": false,
        "reachability": {
          "classification": "internal-only",
          "entry_points": [
